const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<ha-icon icon="mdi:${name}" aria-hidden="true"></ha-icon>`;
const valid=v=>v!==undefined&&v!==null&&!['','unknown','unavailable'].includes(v);
const number=v=>valid(v)&&typeof v!=='boolean'&&Number.isFinite(Number(v))?Number(v):null;
const scope=a=>a?.gwi_scope||a?.gwi_network_id||'legacy';
const hasAlert=c=>c.googleQuality?.key==='weak'||c.signal?.key==='weak';
const hasQuality=c=>c.googleQuality?.key!=='unknown'&&!!c.googleQuality?.key||c.signal?.rssi!=null;
const sourceName=c=>c.signal?.measuredBy==='Shelly'?'shelly':'deviceRadio';

export function filterClients(clients,{query='',point='',filter='all',sort='priority'},language='pt'){
 const normalized=String(query).normalize('NFD').replace(/\p{Diacritic}/gu,'').toLocaleLowerCase(language).trim();
 const matches=c=>[c.uiName,c.name,c.ip,c.mac,c.pointName,c.googleName].filter(Boolean).join(' ').normalize('NFD').replace(/\p{Diacritic}/gu,'').toLocaleLowerCase(language).includes(normalized);
 const selected=clients.filter(c=>(!point||c.pointId===point||(point==='unassigned'&&!c.pointId))&&matches(c)&&(filter==='all'||filter==='issues'&&hasAlert(c)||filter==='rssi'&&c.signal?.rssi!=null||filter==='missing'&&!hasQuality(c)));
 const rank=c=>hasAlert(c)?0:c.googleQuality?.key==='fair'||c.signal?.key==='fair'?1:!hasQuality(c)?2:3;
 return selected.sort((a,b)=>(sort==='priority'?rank(a)-rank(b):sort==='byPoint'?(a.pointName||'').localeCompare(b.pointName||'',language):0)||(a.uiName||a.name).localeCompare(b.uiName||b.name,language));
}

Object.assign(WORDS.en,{unassignedLocation:'No location assigned',localSource:'Local status',cloudSource:'Google account',localHint:'Local status does not include connected devices. A cloud network is needed to see client associations.',setupLocations:'Locations and connection steps'});
Object.assign(WORDS.pt,{unassignedLocation:'Sem localização atribuída',localSource:'Estado local',cloudSource:'Conta Google',localHint:'O estado local não inclui os dispositivos ligados. É necessária uma rede cloud para ver as associações dos clientes.',setupLocations:'Localizações e passos de ligação'});

export function profileLanguage(value,previous='en'){
 const raw=typeof value==='string'?value:value?.language||value?.locale?.language;
 if(typeof raw!=='string'||!raw.trim())return previous;
 return raw.trim().replaceAll('_','-').toLowerCase().split('-')[0]==='pt'?'pt':'en';
}

