 disconnectedCallback(){clearInterval(this._timer);clearTimeout(this._pendingUpdate);this._pendingUpdate=null;for(const unsubscribe of this._contexts.values())unsubscribe();this._contexts.clear();}
 getCardSize(){return 16;}getGridOptions(){return{columns:12,min_columns:6};}
