 _counts(){const cs=this._network?.clients||[];return {all:cs.length,issues:cs.filter(hasAlert).length,rssi:cs.filter(c=>c.signal.rssi!=null).length,missing:cs.filter(c=>!hasQuality(c)).length,known:cs.filter(hasQuality).length};}
 _metric(label,value,foot,action,mdi,alert=false){return `<button class="metric${alert?' alert':''}" data-filter="${action}" aria-label="${escape(label)}: ${escape(value.replace(/<[^>]+>/g,''))}. ${escape(foot)}"><span class="metric-head">${escape(label)}${icon(mdi)}</span><strong class="metric-value">${value}</strong><span class="metric-foot">${escape(foot)}</span></button>`;}
